function doubleArray(numbers) {
  const doubled = []
  for (let i = 0; i < numbers.length; i++) {
    doubled.push(numbers[i] * 2)
  }
  return doubled
}

console.log(doubleArray([1, 2, 3])) // [2, 4, 6]
